-- V11: Create courses table and seed data

CREATE TABLE courses (
    id            UUID PRIMARY KEY,
    code          VARCHAR(20)  NOT NULL UNIQUE,
    name          VARCHAR(255) NOT NULL,
    faculty_id    UUID NOT NULL REFERENCES faculties(id) ON DELETE RESTRICT,
    department_id UUID NOT NULL REFERENCES departments(id) ON DELETE RESTRICT,
    academician_id UUID NOT NULL REFERENCES academicians(id) ON DELETE RESTRICT,
    theoretical_hours INTEGER NOT NULL DEFAULT 2,
    practical_hours   INTEGER NOT NULL DEFAULT 0,
    ects          INTEGER NOT NULL DEFAULT 3,
    credits       INTEGER NOT NULL DEFAULT 2,
    course_type   VARCHAR(20)  NOT NULL DEFAULT 'ZORUNLU',
    semester      VARCHAR(20)  NOT NULL DEFAULT 'GUZ',
    grade         INTEGER      NOT NULL DEFAULT 1,
    active        BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

